fn point<R: Real>(s: &mut String, p: &str, o: &ManifoldPoint<R>) {
    let [hi,lo] = o.local_point1.x.to_words();
    write!(s,"{p}local_point1.x={hi:08x}{lo:08x};").unwrap();
    let [hi,lo] = o.local_point1.y.to_words();
    write!(s,"{p}local_point1.y={hi:08x}{lo:08x};").unwrap();
    let [hi,lo] = o.local_point2.x.to_words();
    write!(s,"{p}local_point2.x={hi:08x}{lo:08x};").unwrap();
    let [hi,lo] = o.local_point2.y.to_words();
    write!(s,"{p}local_point2.y={hi:08x}{lo:08x};").unwrap();
    let [hi,lo] = o.separation.to_words();
    write!(s,"{p}separation={hi:08x}{lo:08x};").unwrap();
    let [hi,lo] = o.normal_impulse.to_words();
    write!(s,"{p}normal_impulse={hi:08x}{lo:08x};").unwrap();
    let [hi,lo] = o.tangent_impulse.to_words();
    write!(s,"{p}tangent_impulse={hi:08x}{lo:08x};").unwrap();
    write!(s,"{p}id={};",o.id).unwrap();
}

pub(crate) fn observe_body<R:Real>(s:&mut String,p:&str,b:&Body<R>) { body(s,p,b); }
pub(crate) fn observe_joint<R:Real>(s:&mut String,p:&str,j:&Joint<R>) {
    joint(s,p,j);
    match j.type_ { 1=>revolute(s,p,j),2=>prismatic(s,p,j),3=>distance(s,p,j),6=>gear(s,p,j),_=>panic!("unknown joint") }
}
pub fn physics_string<R: Real>(ctx: &Ctx<R>) -> String {
    let w = &ctx.world;
    let mut s = String::new();
    world(&mut s,"world.",w);
    let mut h = w.body_list;
    let mut bi = 0;
    while h != NONE {
        let b = w.body(h);
        let p = format!("bodies[{bi}].");
        body(&mut s,&p,b);
        let mut sh = b.shape_list;
        let mut si = 0;
        while sh != NONE {
            let o = w.shape(sh);
            let p = format!("bodies[{bi}].shapes[{si}].");
            shape(&mut s,&p,o);
            if o.type_ == 0 { circle(&mut s,&p,o); }
            else {
                polygon(&mut s,&p,o);
                for k in 0..o.vertex_count as usize {
                    for (name, v) in [("vertices",o.vertices[k]),("normals",o.normals[k]),("core_vertices",o.core_vertices[k])] {
                        for (axis,n) in [("x",v.x),("y",v.y)] {
                            let [hi,lo] = n.to_words();
                            write!(s,"{p}{name}[{k}].{axis}={hi:08x}{lo:08x};").unwrap();
                        }
                    }
                }
            }
            sh=o.next; si+=1;
        }
        h=b.next; bi+=1;
    }
    h=w.joint_list;
    let mut ji=0;
    while h != NONE {
        let j=w.joint(h);
        let p=format!("joints[{ji}].");
        joint(&mut s,&p,j);
        match j.type_ {
            1 => revolute(&mut s,&p,j), 2 => prismatic(&mut s,&p,j),
            3 => distance(&mut s,&p,j), 6 => gear(&mut s,&p,j), _ => panic!("unobserved joint type"),
        }
        h=j.next; ji+=1;
    }
    h=w.contact_list;
    let mut ci=0;
    while h != NONE {
        let c=w.contact(h);
        let p=format!("contacts[{ci}].");
        contact(&mut s,&p,c);
        manifold(&mut s,&format!("{p}manifold."),&c.manifold);
        for k in 0..2 { point(&mut s,&format!("{p}manifold.points[{k}]."),&c.manifold.points[k]); }
        h=c.next; ci+=1;
    }
    s
}
